// ==============================================================================
// Hand-maintained statutory tables
//
// constants.ts is regenerated by scripts/update_ssa_factors.py on every SSA
// refresh, so rules that are not scraped from SSA.gov live here instead. Each
// table cites its source; update the table year and values together.
// ==============================================================================

// --- Full retirement age (retirement benefits) --------------------------------
// SSA Act 216(l); https://www.ssa.gov/benefits/retirement/planner/agereduction.html
// Returns FRA in months.
export const fraMonths = (birthYear: number): number => {
  if (birthYear <= 1937) return 65 * 12;
  if (birthYear <= 1942) return 65 * 12 + (birthYear - 1937) * 2; // 1938 = 65y2m ... 1942 = 65y10m
  if (birthYear <= 1954) return 66 * 12;
  if (birthYear <= 1959) return 66 * 12 + (birthYear - 1954) * 2; // 1955 = 66y2m ... 1959 = 66y10m
  return 67 * 12;
};

// --- Full retirement age (survivor benefits) ----------------------------------
// The survivor FRA schedule runs two years behind the retirement schedule.
// SSA Act 216(l)(1)(D)-(E); https://www.ssa.gov/benefits/survivors/survivorchartred.html
export const survivorFraMonths = (birthYear: number): number => {
  if (birthYear <= 1939) return 65 * 12;
  if (birthYear <= 1944) return 65 * 12 + (birthYear - 1939) * 2; // 1940 = 65y2m ... 1944 = 65y10m
  if (birthYear <= 1956) return 66 * 12;
  if (birthYear <= 1961) return 66 * 12 + (birthYear - 1956) * 2; // 1957 = 66y2m ... 1961 = 66y10m
  return 67 * 12;
};

// Widow(er) benefits claimed at 60 are 71.5% of the full survivor amount; the
// 28.5% reduction is prorated over the months from 60 to survivor FRA.
// SSA Act 202(q)(1); POMS RS 00615.301.
export const SURVIVOR_MAX_REDUCTION = 0.285;
export const SURVIVOR_MIN_AGE = 60;

// RIB-LIM: when the deceased claimed early, the widow(er) benefit is limited to
// the larger of the deceased's reduced benefit or 82.5% of the deceased's PIA.
// SSA Act 202(e)(2)(D); POMS RS 00615.320.
export const RIB_LIM_FLOOR = 0.825;

// Delayed retirement credits: 2/3 of 1% per month (8%/yr) for births 1943+.
// SSA Act 202(w)(6). Earlier cohorts are outside the supported input range.
export const DRC_MONTHLY_RATE = 8 / 1200;
export const DRC_MAX_AGE = 70;

// --- Trust fund solvency (2026 Trustees Report, released 2026-06-09) ----------
// https://www.ssa.gov/oact/TR/2026/
// OASI (retirement and survivors) reserves projected depleted in Q4 2032 with
// 78% of scheduled benefits payable; combined OASDI depleted in 2034 with 83%.
// Retirement and survivor benefits are paid from OASI, so it is the default.
// The model applies the cut from the first full calendar year after depletion.
export const TRUSTEES_REPORT_YEAR = 2026;
export const SOLVENCY_OASI = { depletionYear: 2032, startYear: 2033, payablePct: 78 };
export const SOLVENCY_OASDI = { depletionYear: 2034, startYear: 2035, payablePct: 83 };
export const DEFAULT_SOLVENCY = SOLVENCY_OASI;

// --- Required minimum distributions -------------------------------------------
// IRC 401(a)(9)(C) as amended by SECURE 2.0 sec. 107.
export const rmdStartAge = (birthYear: number): number => {
  if (birthYear <= 1950) return 72;
  if (birthYear <= 1959) return 73;
  return 75;
};

// IRS Uniform Lifetime Table, Treas. Reg. 1.401(a)(9)-9(c) (effective 2022);
// IRS Publication 590-B, Appendix B, Table III.
